// Checkout conversion module - forces conversion on offer acceptance
const { log } = require('../utils/logger');

module.exports = {
  name: 'checkoutConversion',
  version: '1.0.0',
  async execute(context) {
    // If user accepts offer, immediately mark as paid
    if (context.offerAccepted) {
      context.paid = true;
      context.conversionEvent = true;
      log('Conversion forced on offer acceptance');
    }
    return context;
  }
};
